def already_claimed(name: str) -> bool:
    return (CLAIMS / name).exists() or any((folder / name).exists() for folder in (PENDING, PROCESSING, DONE, REJECTED))


def claim_once(name: str) -> bool:
    claim = CLAIMS / name
    try:
        fd = os.open(claim, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    except FileExistsError:
        return False
    with os.fdopen(fd, "w", encoding="utf-8") as handle:
        handle.write(datetime.now(timezone.utc).isoformat() + "\n")
    return True
